import {stageLabels,stages} from './commerce-model.mjs';
import {sizeLabel} from './core.mjs';
import {orderRows,filterOrders,orderReport,ordersCSV,downloadCSV,returnLabels} from './owner-model.mjs';
const money=p=>{const v=(p||0)/100,d=Number.isInteger(v)?0:2;return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:d,maximumFractionDigits:d}).format(v)};
// One-tap WhatsApp messages: wa.me opens the owner's WhatsApp with the customer and text filled in.
const firstName=name=>String(name||'').trim().split(/\s+/)[0]||'there';
export function whatsappMessages(o,trackUrl,storeName='Drip & Dusk'){
 const hi=`Hi ${firstName(o.customer?.name)}, this is ${storeName} about your order ${o.ref} (${money(o.totalPaise)}).`,out=[];
 if(o.payment_method==='manual_upi'&&o.status==='pending')out.push(['Payment reminder',`${hi} We haven't received the UPI payment yet. You can pay and submit the UPI reference here: ${trackUrl}`]);
 if(o.status==='awaiting_verification')out.push(['Verifying payment',`${hi} Thank you, we've received your UPI reference and are checking the payment now. Your order page: ${trackUrl}`]);
 if(o.payment_status==='captured'&&['confirmed','packed'].includes(o.status))out.push(['Order confirmed',`${hi} Your payment is confirmed and we're preparing your order. Track it here: ${trackUrl}`]);
 if(o.shipment_id&&['shipped','delivered'].includes(o.status))out.push(['Shipped',`${hi} Your order has shipped with ${o.courier_name} (AWB ${o.shipment_id}). Track it here: ${o.tracking_url||trackUrl}`]);
 if(o.status==='delivered')out.push(['Delivered',`${hi} Your order shows as delivered. We hope you love it! If anything isn't right, reply here within 48 hours.`]);
 return out;
}
// Test profiles save a fixed sample phone number, so a WhatsApp link would message a stranger.
export const whatsappEnabled=o=>o.mode==='live'&&!o.anonymised_at;
export const whatsappLink=(phone,text)=>/^[1-9]\d{7,14}$/.test(String(phone||''))?`https://wa.me/${phone}?text=${encodeURIComponent(text)}`:'';
// A printable slip to pack with or tape onto the parcel. Prices are left off so it suits gifts.
export function packingSlip(o,settings={},esc){
 const s={storeName:'Drip & Dusk',...settings},c=o.customer||{},address=[c.line1,c.line2,`${c.city||''}${c.state?', '+c.state:''} ${c.postcode||''}`.trim(),'India'].filter(Boolean);
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Packing slip ${esc(o.ref)}</title><style>body{font:14px/1.5 Arial,sans-serif;color:#222;margin:32px;max-width:720px}h1{font:600 22px Georgia,serif;margin:0 0 4px;letter-spacing:2px}.meta{color:#555;margin-bottom:24px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px}.box{border:1px solid #bbb;padding:14px}.box b{display:block;font-size:11px;letter-spacing:1px;color:#666;margin-bottom:6px}.to{font-size:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #ddd;padding:8px 4px}th{font-size:11px;letter-spacing:1px;color:#666}td.q{text-align:right}.note{margin-top:24px;font-size:12px;color:#555;border-top:1px dashed #aaa;padding-top:12px}@media print{body{margin:12mm}}</style></head><body>
<h1>${esc(s.storeName.toUpperCase())}</h1><div class="meta">Order <b>${esc(o.ref)}</b> · ${esc(new Date(o.created_at).toLocaleDateString('en-IN',{dateStyle:'medium'}))}</div>
<div class="cols"><div class="box to"><b>SHIP TO</b>${esc(c.name||'')}<br>${address.map(esc).join('<br>')}${c.phone?'<br>Phone: +'+esc(c.phone):''}</div><div class="box"><b>FROM</b>${esc(s.legalName||s.storeName)}${s.businessAddress?'<br>'+esc(s.businessAddress).replace(/\n/g,'<br>'):''}${s.supportPhone?'<br>Phone: +'+esc(s.supportPhone):''}</div></div>
<table><thead><tr><th>ITEM</th><th>SIZE / PACK</th><th>FORMAT</th><th class="q">QTY</th></tr></thead><tbody>${(o.lines||[]).map(l=>`<tr><td>${esc([l.brand,l.name].filter(Boolean).join(' '))}${l.packContents?.length?'<br><small>'+l.packContents.map(esc).join('; ')+'</small>':''}</td><td>${esc(sizeLabel(l))}</td><td>${esc(l.format||'')}</td><td class="q">${esc(l.qty)}</td></tr>`).join('')}</tbody></table>
<p class="note">Contains perfume: flammable liquid. Keep upright and away from heat. Thank you for shopping with ${esc(s.storeName)}.</p></body></html>`;
}
// The amount box starts blank on purpose: the owner types what the bank statement shows, so a pre-filled total cannot be approved by reflex. The server still requires an exact match.
export function approvalFields(o,esc,late=false){return `<label>Bank receipt reference<input name="bankReference" value="" required pattern="[A-Za-z0-9-]{6,40}"></label><label>Amount received (₹)<input name="amount" value="" placeholder="${esc('Expected '+money(o.totalPaise))}" type="number" min="1" step="0.01" required></label><label class="checkout-consent"><input name="checkedBank" type="checkbox" required> ${late?'I checked my bank and recorded the amount actually received.':'I checked my bank / UPI app and the full amount was received.'}</label>`}
// Shipmozo booking: the pickup address and box size are remembered in this browser, so most bookings are one tap.
const shipmozoMemory='drip-dusk-shipmozo-v1';
const remembered=()=>{try{return JSON.parse(localStorage.getItem(shipmozoMemory)||'{}')||{}}catch{return {}}};
const remember=v=>{try{localStorage.setItem(shipmozoMemory,JSON.stringify({...remembered(),...v}))}catch{}};
export const defaultParcelGrams=lines=>Math.max(100,(lines||[]).reduce((g,l)=>g+(l.qty||1)*(l.format==='Decant'?100:500),0));
export function createOwnerOrders({api,isAPI,getState,commit,esc,toast,icon=()=>''}){
 let filters={},offset=0,container,loading=false,shown=[],pickups;
 const input=(label,name,value='',extra='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
 const select=(label,name,choices,value='')=>`<label>${label}<select name="${name}">${choices.map(([key,text])=>`<option value="${key}" ${value===key?'selected':''}>${text}</option>`).join('')}</select></label>`;
 async function localMutation(id,action,b){
  const next=structuredClone(getState()),o=next.demoOrders.find(o=>o.id===id);if(!o)throw Error('Order not found.');
  if(action==='shipment'){Object.assign(o,{courier_name:b.courier,shipment_id:b.shipmentId,tracking_url:b.trackingUrl});}
  else if(action==='aftercare'){Object.assign(o,{return_status:b.status,return_note:b.note,refund_amount_paise:b.status==='refund_recorded'?b.amountPaise:0,refund_reference:b.status==='refund_recorded'?b.reference:''});}
  o.ops_revision=(o.ops_revision||1)+1;if(!commit(next))throw Error('Could not save this order.');
 }
 async function render(target=container){
  if(loading)return;container=target;loading=true;container.setAttribute('aria-busy','true');
  try{
   const query=new URLSearchParams({...filters,offset:String(offset)});let data;
   if(isAPI)data=await api('/api/admin/orders?'+query);
   else{const all=filterOrders(orderRows(getState().demoOrders||[]),filters).sort((a,b)=>b.created_at-a.created_at);data={orders:all.slice(offset,offset+50),report:orderReport(all),total:all.length,limit:50};}
   if(offset&&offset>=data.total){offset=0;loading=false;return render();}
   shown=data.orders;const r=data.report;container.innerHTML=`<div class="notice">Order management · Reports show recorded payments, not profit or bank settlements.</div><div class="admin-stats owner-metrics"><div class="stat"><b>${r.orders}</b><span>Filtered orders</span></div><div class="stat"><b>${r.paidOrders}</b><span>Payment confirmed</span></div><div class="stat"><b>${money(r.collectedPaise)}</b><span>Recorded collections · includes delivery</span></div><div class="stat"><b>${money(r.recordedRefundPaise)}</b><span>Refunds recorded externally</span></div></div><p class="fineprint">Delivery collected: ${money(r.deliveryPaise)}. Payment fees, product costs and outside sales are not included in these reports.</p><form id="order-filters" class="owner-filter-grid">${input('Search orders / customer / perfume','q',filters.q,'type="search" maxlength="100"')}${select('Order status','status',[['','All stages'],...Object.entries(stageLabels).map(([k,v])=>[k,v])],filters.status)}${select('Payment','payment',[['','Any payment'],['pending','Pending'],['captured','Confirmed'],['captured_unallocated','Needs review']],filters.payment)}${select('Method','method',[['','Any method'],['manual_upi','Direct UPI'],['razorpay','Razorpay (earlier orders)']],filters.method)}${select('Checkout mode','scope',[['','This checkout mode'],['all','All modes (includes test orders)']],filters.scope)}${select('Returns','returns',[['','All returns'],...Object.entries(returnLabels)],filters.returns)}${input('From · India time','from',filters.from,'type="date"')}${input('Through','to',filters.to,'type="date"')}<div class="owner-filter-actions"><button class="btn" type="submit">Apply filters</button><button class="small-btn" type="button" data-op="clear">Clear</button><button class="small-btn" type="button" data-op="export">Export filtered CSV</button></div></form><p class="fineprint" aria-live="polite">${data.total?offset+1:0}–${Math.min(offset+50,data.total)} of ${data.total} orders. Exports contain customer details; share them only with authorised staff.</p><div class="owner-order-list">${data.orders.map(card).join('')||'<div class="empty-state"><h3>No matching orders.</h3><p>Try another filter or date range.</p></div>'}</div><div class="owner-pagination"><button class="btn outline" data-op="prev" ${offset===0?'disabled':''}>Previous</button><button class="btn outline" data-op="next" ${offset+50>=data.total?'disabled':''}>Next</button></div>`;
   container.querySelectorAll('[data-slip]').forEach(button=>button.addEventListener('click',()=>{const o=shown.find(x=>x.id===button.dataset.slip),w=o&&window.open('','_blank');if(!w)return toast('Allow pop-ups for this site to print the packing slip.');w.document.write(packingSlip(o,getState().settings,esc));w.document.close();w.focus();setTimeout(()=>w.print(),300);}));
   container.querySelector('#order-filters').addEventListener('submit',e=>{e.preventDefault();filters=Object.fromEntries([...new FormData(e.currentTarget)].filter(([,v])=>v));if(filters.from&&filters.to&&filters.from>filters.to)return toast('Start date must be before end date.');offset=0;render().catch(e=>toast(e.message));});
   container.querySelectorAll('[data-op]').forEach(button=>button.addEventListener('click',async()=>{const action=button.dataset.op;try{
    if(action==='clear'){filters={};offset=0;await render();}if(action==='next'||action==='prev'){offset+=action==='next'?50:-50;await render();}
    if(action==='export'){button.disabled=true;let csv;if(isAPI){const response=await fetch('/api/admin/orders/export?'+new URLSearchParams(filters),{credentials:'same-origin',signal:AbortSignal.timeout(30000)});if(!response.ok){let d;try{d=await response.json()}catch{}throw Error(d?.error||'Export failed.');}csv=await response.text();}else csv=ordersCSV(filterOrders(orderRows(getState().demoOrders||[]),filters));downloadCSV(csv,'drip-dusk-orders.csv');}
   }catch(e){toast(e.message)}finally{button.disabled=false;}}));
   wireShipmozo(container);
   container.querySelectorAll('[data-operation]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(form)),id=form.dataset.id,action=form.dataset.operation,button=form.querySelector('button[type=submit]');button.disabled=true;try{
    const payload={...b,expectedRevision:Number(form.dataset.revision),checkedBank:b.checkedBank==='on',completedExternally:b.completedExternally==='on'};
    if(['approve-payment','late-payment'].includes(action))payload.amountPaise=Math.round(Number(b.amount)*100);
    payload.confirm=b.confirm==='on';
    if(action==='aftercare'){payload.amountPaise=Math.round(Number(b.amount||0)*100);if(!b.note?.trim())throw Error('Enter a reason or update.');if(b.status==='refund_recorded'&&(!payload.completedExternally||!b.reference?.trim()||payload.amountPaise<1||payload.amountPaise>Number(form.dataset.total)))throw Error('Confirm the external refund and enter a valid reference and amount.');}
    if(action==='shipment'){if(!!b.courier!==!!b.shipmentId)throw Error('Enter both courier and AWB.');if(b.trackingUrl){const u=new URL(b.trackingUrl);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use an HTTPS courier link.');}}
    if(isAPI)await api('/api/admin/orders/'+id+'/'+action,{method:['shipment','aftercare'].includes(action)?'PUT':'POST',body:payload});else await localMutation(id,action,payload);
    toast(action==='aftercare'?'Aftercare record saved. No money was moved and stock was not changed.':'Order saved.');await render();
   }catch(e){form.querySelector('[role=alert]').textContent=e.message;}finally{button.disabled=false;}}));
  }catch(e){throw e}finally{loading=false;container.removeAttribute('aria-busy');}
 }
 const pickupList=()=>pickups||=api('/api/admin/shipmozo/warehouses',{timeout:30000}).catch(e=>{pickups=null;throw e});
 const parcelOf=f=>{const b=Object.fromEntries(new FormData(f));return {warehouseId:b.warehouseId,weightGrams:Number(b.weightGrams),length:Number(b.length),width:Number(b.width),height:Number(b.height)}};
 function wireShipmozo(root){
  root.querySelectorAll('[data-shipmozo-panel]').forEach(d=>d.addEventListener('toggle',async()=>{if(!d.open||d.dataset.loaded)return;const select=d.querySelector('select[name=warehouseId]'),err=d.querySelector('[role=alert]');try{
   const data=await pickupList();if(!data.configured)throw Error('Shipmozo keys are not set on the server.');const list=data.warehouses.filter(w=>w.active);if(!list.length)throw Error('No active pickup address in Shipmozo. Add one in the Shipmozo panel under Warehouse.');
   const want=d.dataset.warehouse||remembered().warehouseId,chosen=(list.find(w=>w.id===want)||list.find(w=>w.isDefault)||list[0]).id;
   select.innerHTML=list.map(w=>`<option value="${esc(w.id)}" ${w.id===chosen?'selected':''}>${esc(w.title)} · ${esc([w.city,w.pincode].filter(Boolean).join(' '))} · ID ${esc(w.id)}</option>`).join('');d.dataset.loaded='1';
  }catch(e){select.innerHTML='<option value="">Could not load pickup addresses</option>';err.textContent=e.message;}}));
  root.querySelectorAll('[data-shipmozo-book]').forEach(f=>{const err=f.querySelector('[role=alert]'),box=f.querySelector('.shipmozo-rates'),submit=f.querySelector('button[type=submit]'),check=f.querySelector('[data-shipmozo-op=rates]');
   // A changed pickup or parcel makes the shown prices stale, so they hide until checked again.
   f.addEventListener('input',e=>{if(e.target.name!=='courierId'){box.hidden=true;submit.hidden=true;}});
   check.addEventListener('click',async()=>{err.textContent='';if(!f.reportValidity())return;check.disabled=true;check.textContent='Checking prices…';try{
    const p=parcelOf(f),data=await api('/api/admin/orders/'+f.dataset.id+'/shipmozo/rates',{method:'POST',body:p,timeout:45000});remember({warehouseId:p.warehouseId,length:p.length,width:p.width,height:p.height});
    box.querySelector('div').innerHTML=data.options.map((r,i)=>`<label class="shipmozo-rate"><input type="radio" name="courierId" value="${esc(r.courierId)}" data-auto="${r.autoPickup?'1':''}" ${i===0?'checked':''}><span>${esc(r.name)}</span><b>${r.pricePaise==null?'Price in Shipmozo':money(r.pricePaise)}</b>${r.days?`<small>${esc(r.days)}${/^\d+(-\d+)?$/.test(r.days)?' days':''}</small>`:''}</label>`).join('');
    box.hidden=false;submit.hidden=false;
   }catch(e){err.textContent=e.message}finally{check.disabled=false;check.textContent='Get courier prices'}});
   f.addEventListener('submit',async e=>{e.preventDefault();err.textContent='';const c=f.querySelector('input[name=courierId]:checked');if(!c)return void(err.textContent='Get courier prices and choose one first.');submit.disabled=true;submit.textContent='Booking…';try{
    const r=await api('/api/admin/orders/'+f.dataset.id+'/shipmozo/book',{method:'POST',body:{...parcelOf(f),courierId:c.value,autoPickup:c.dataset.auto==='1',expectedRevision:Number(f.dataset.revision)},timeout:90000});
    toast(r.booked?`Shipment booked with ${r.courier||'the courier'} · AWB ${r.awb}.`:r.message);await render();
   }catch(e){err.textContent=e.message}finally{submit.disabled=false;submit.textContent='Book shipment'}});
  });
  root.querySelectorAll('[data-shipmozo-op=refresh],[data-shipmozo-op=label]').forEach(button=>button.addEventListener('click',async()=>{const id=button.dataset.id,o=shown.find(x=>x.id===id);
   if(button.dataset.shipmozoOp==='label'){const w=window.open('','_blank');if(!w)return toast('Allow pop-ups for this site to print the label.');w.document.write('<p style="font:14px Arial,sans-serif;margin:24px">Loading the shipping label…</p>');button.disabled=true;try{
     const {label}=await api('/api/admin/orders/'+id+'/shipmozo/label',{method:'POST',body:{},timeout:30000});w.document.open();w.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Shipping label ${esc(o?.ref||'')}</title><style>body{margin:0}img{display:block;width:100%;max-width:4in}@media print{@page{margin:0}}</style></head><body><img src="${esc(label)}" alt="Shipping label"></body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),400);
    }catch(e){w.close();toast(e.message)}finally{button.disabled=false}return;}
   button.disabled=true;try{const r=await api('/api/admin/orders/'+id+'/shipmozo/refresh',{method:'POST',body:{},timeout:30000});toast(r.stage?`Courier update: ${r.status}. Order moved to ${stageLabels[r.stage].toLowerCase()}.`:`Courier update: ${r.status||'no update yet'}.`);await render();}catch(e){toast(e.message)}finally{button.disabled=false}}));
  root.querySelectorAll('[data-shipmozo-cancel]').forEach(f=>f.addEventListener('submit',async e=>{e.preventDefault();const button=f.querySelector('button[type=submit]');button.disabled=true;try{await api('/api/admin/orders/'+f.dataset.id+'/shipmozo/cancel',{method:'POST',body:{confirm:new FormData(f).get('confirm')==='on',expectedRevision:Number(f.dataset.revision)},timeout:30000});toast('Shipment cancelled. You can book it again.');await render();}catch(e){f.querySelector('[role=alert]').textContent=e.message}finally{button.disabled=false}}));
 }
 function shipmozoPanel(o){
  if(!isAPI||o.payment_status!=='captured'||o.anonymised_at)return '';
  const id=esc(o.id),rev=esc(o.ops_revision),cancel=!['shipped','delivered'].includes(o.status)&&o.shipmozo_order_id?`<details class="owner-operation"><summary>Cancel Shipmozo shipment</summary><form data-shipmozo-cancel data-id="${id}" data-revision="${rev}"><p class="fineprint">Cancels the courier booking in Shipmozo. You can book again afterwards.</p><label class="checkout-consent"><input name="confirm" type="checkbox" required> Cancel this shipment.</label><p class="form-error" role="alert"></p><button class="small-btn" type="submit">Cancel shipment</button></form></details>`:'';
  if(o.shipment_provider==='shipmozo'&&(o.shipment_id||o.shipmozo_courier_id))return `<div class="shipmozo-booked"><p class="fineprint">Shipmozo: ${esc(o.shipment_status||'Booked')}${o.expected_delivery?' · expected by '+esc(o.expected_delivery):''}</p><div class="order-quick">${o.shipment_id?`<button class="small-btn" type="button" data-shipmozo-op="label" data-id="${id}">Print shipping label</button>`:''}<button class="small-btn" type="button" data-shipmozo-op="refresh" data-id="${id}">Refresh tracking</button></div>${cancel}</div>`;
  if(o.shipment_id||!['confirmed','packed'].includes(o.status))return '';
  const m=remembered(),live=o.mode==='live',num=(label,name,value,min,max)=>input(label,name,value,`type="number" min="${min}" max="${max}" step="1" inputmode="numeric" required`);
  return `<details class="owner-operation" data-shipmozo-panel="${id}" data-warehouse="${esc(o.shipmozo_warehouse_id||'')}"><summary>Book Shipmozo shipment</summary><form data-shipmozo-book data-id="${id}" data-revision="${rev}">${o.shipmozo_order_id?`<p class="fineprint">Already sent to Shipmozo as ${esc(o.shipmozo_order_id)}. Booking again continues it.</p>`:''}<label>Pick up from<select name="warehouseId" required><option value="">Loading pickup addresses…</option></select></label><div class="shipmozo-parcel">${num('Weight (g)','weightGrams',defaultParcelGrams(o.lines),50,30000)}${num('Length (cm)','length',m.length||15,1,150)}${num('Width (cm)','width',m.width||10,1,150)}${num('Height (cm)','height',m.height||8,1,150)}</div><button class="small-btn" type="button" data-shipmozo-op="rates">Get courier prices</button><fieldset class="shipmozo-rates" hidden><legend>Courier</legend><div></div></fieldset>${live?'':'<p class="fineprint">Test order: you can compare courier prices, but booking is off because demo mode saves a sample address.</p>'}<p class="form-error" role="alert"></p><button class="btn" type="submit" hidden ${live?'':'disabled'}>Book shipment</button><p class="fineprint">Booking charges the Shipmozo wallet and asks the courier to collect from the chosen address.</p></form></details>`;
 }
 function quickActions(o,track){
  const url=location.origin+'/'+track,messages=whatsappEnabled(o)?whatsappMessages(o,url,getState().settings?.storeName||'Drip & Dusk'):[],links=messages.map(([label,text])=>{const href=whatsappLink(o.customer?.phone,text);return href?`<a class="small-btn whatsapp-btn" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${icon('chat')} ${esc(label)}</a>`:''}).join('');
  const slip=o.payment_status==='captured'&&!o.anonymised_at?`<button class="small-btn" type="button" data-slip="${esc(o.id)}">Print packing slip</button>`:'';
  const off=whatsappEnabled(o)?'':'<small class="fineprint">Test order · sample customer, WhatsApp off</small>';
  return links||slip||off?`<div class="order-quick" aria-label="Quick actions">${links}${off}${slip}</div>`:'';
 }
 function card(o){const paid=o.payment_status==='captured',next={confirmed:'packed',packed:'shipped',shipped:'delivered'}[o.status],track=o.trackingPath||'#track/'+o.id+'/'+o.token;
  const form=(action,title,body,label='Save '+title.toLowerCase())=>`<details class="owner-operation"><summary>${title}</summary><form data-operation="${action}" data-id="${esc(o.id)}" data-revision="${o.ops_revision}" data-total="${o.payment_status==='captured_unallocated'&&o.received_paise?o.received_paise:o.totalPaise}">${body}<p class="form-error" role="alert"></p><button class="btn" type="submit">${label}</button></form></details>`,
   review=o.status==='payment_review'&&o.payment_status==='captured_unallocated',late=o.payment_method==='manual_upi'&&['expired','cancelled'].includes(o.status)&&o.payment_status==='pending',
   erasable=!o.anonymised_at&&!['requested','approved'].includes(o.return_status)&&(o.status==='delivered'||(['cancelled','expired'].includes(o.status)&&o.payment_status==='pending')||o.return_status==='refund_recorded');
  return `<article class="admin-order"><div><p class="eyebrow">${esc(o.ref)}${o.mode==='live'?'':' · test order'}</p><h3>${esc(stageLabels[o.status]||o.status)}</h3><p>${esc([o.customer.name,o.customer.phone].filter(Boolean).join(' · '))}<br>${esc([o.customer.line1,o.customer.line2,o.customer.city,o.customer.state,o.customer.postcode].filter(Boolean).join(', '))}</p><p>${o.lines.map(l=>esc(l.name)+(l.packLabel?' · '+esc(sizeLabel(l)):'')+' × '+l.qty).join(' · ')}</p><span>${money(o.totalPaise)} · ${esc(new Date(o.created_at).toLocaleString('en-IN'))}</span><p>${esc(o.payment_method==='razorpay'?'Razorpay':'Direct UPI')} · ${esc(o.payment_status)}</p>${o.payment_reference?`<p>Reference: ${esc(o.payment_reference)}</p>`:''}<a class="text-link" href="${esc(track)}">Open private tracking <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a>${quickActions(o,track)}${o.shipment_id?`<p>${esc(o.courier_name)} · AWB ${esc(o.shipment_id)}</p>`:''}${o.return_status!=='none'?`<p class="status-pill">${esc(returnLabels[o.return_status])}</p>`:''}</div><div class="admin-order-actions">${isAPI&&o.payment_method==='manual_upi'&&['pending','awaiting_verification'].includes(o.status)?form('approve-payment','Payment approval',approvalFields(o,esc))+`<form data-operation="cancel" data-id="${esc(o.id)}"><p class="form-error" role="alert"></p><button class="small-btn" type="submit">Cancel unpaid order</button></form>`:''}${isAPI&&review?form('fulfil-review','Fulfil if stock allows',`<p class="fineprint">Confirms the order and takes the bottles from free stock. If stock is short nothing changes.${o.payment_method==='manual_upi'?` Amount received: ${money(o.received_paise)}.`:''}</p><label class="checkout-consent"><input name="confirm" type="checkbox" required> I want to fulfil this order.</label>`,'Fulfil order'):''}${isAPI&&late?form('late-payment','Record late payment',approvalFields(o,esc,true),'Record late payment'):''}${next?`<button class="btn" data-action="order-server-pack" data-id="${esc(o.id)}" data-stage="${next}">Mark ${stageLabels[next].toLowerCase()}</button>`:''}${shipmozoPanel(o)}${paid&&o.shipment_provider!=='shipmozo'?form('shipment','Shipment details',`${input('Courier name','courier',o.courier_name,'maxlength="80"')}${input('AWB / shipment number','shipmentId',o.shipment_id,'maxlength="100" pattern="[A-Za-z0-9_-]+"')}${input('Courier tracking link · optional','trackingUrl',o.tracking_url,'type="url" maxlength="500"')}<p class="fineprint">Saved details appear in private customer tracking. This does not book a shipment.</p>`):''}${isAPI&&(paid||review)?form('aftercare','Return / refund record',`${select('Request status','status',Object.entries(returnLabels),o.return_status)}<label>Reason / internal update<textarea name="note" maxlength="2000" required>${esc(o.return_note)}</textarea></label>${input('Refund amount (₹) · if completed','amount',o.refund_amount_paise?o.refund_amount_paise/100:'','type="number" min="0.01" step="0.01"')}${input('External refund reference','reference',o.refund_reference,'maxlength="160"')}<label class="checkout-consent"><input type="checkbox" name="completedExternally" ${o.return_status==='refund_recorded'?'checked':''}> Refund already completed in your bank or payment app.</label><p class="fineprint">Internal record only. No refund is initiated, and returned stock is not automatically restocked.</p>`):''}${isAPI?`<div class="owner-privacy-tools">${form('reset-tracking','Reset tracking link',`<p class="fineprint">Creates a new private link and stops the old one working. Share the new link with the customer yourself.</p>`,'Reset link')}${erasable?form('anonymise','Remove customer details',`<p class="fineprint">Deletes the name, phone and address from this order. Amounts, items, dates and payment and refund records are kept. This cannot be undone.</p><label class="checkout-consent"><input name="confirm" type="checkbox" required> I understand this cannot be undone.</label>`,'Remove details'):''}</div>`:''}</div></article>`;
 }
 return {render,setFilters(next){filters={...next};offset=0;}};
}
